#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    sort(v.begin(), v.end(), [](int a, int b) {
        return a > b;
    });

    cout << v[0] << endl;
    cout << v[v.size() - 1] << endl;
    return 0;
}
